var e={id:`lukas-oppdrag`,episode:1,door:1,title:{nb:`Lukas’ oppdrag`,en:`Luke’s assignment`},reference:`Luk 1,1–4`,place:`cesarea`,prologue:[{image:`art/lukas.webp`,text:{nb:`Lukas er lege, forteller tradisjonen. Han har hørt mye om Jesus fra Nasaret, men skriver selv at han har det fra dem som var øyenvitner.`,en:`Luke is a physician, tradition says. He has heard much about Jesus of Nazareth, but he writes himself that he got it from those who were eyewitnesses.`}},{image:`art/lukas.webp`,text:{nb:`Nå vil han skrive det ned. Da må han vite hvem som faktisk så det som skjedde, og hvem som bare gjentar det andre har sagt.`,en:`Now he wants to write it down. So he must know who actually saw what happened, and who is only repeating what others have said.`}},{image:`maps/cesarea-torg.webp`,text:{nb:`I havnebyen Cæsarea tar han deg i lære. Det første du må lære, er dette: Hvordan skiller du et øyenvitne fra et rykte?`,en:`In the harbour city of Caesarea he takes you on as his apprentice. The first thing you must learn is this: how do you tell an eyewitness from a rumour?`}}],intro:{nb:`Cæsarea, en morgen ved havna. Lukas venter på deg i skrivestua.`,en:`Caesarea, a morning by the harbour. Luke is waiting for you in his writing room.`},outro:{nb:`Var vitnet der selv? Kan noe bekrefte det? Har vitnet noe å vinne?`,en:`Was the witness there? Can anything confirm it? Does the witness have something to gain?`},map:[`################..##############`,`################..##############`,`##############....##############`,`#############.......############`,`############........############`,`#########......##.......########`,`##########.....###...###########`,`###########..........###########`,`###########.........############`,`######.#...###...##...##########`,`#####......###...##...##########`,`#####..#######...########.###..#`,`................................`,`..#.#..#.##..#....#..#..#..#.#..`,`########.##..#....#..#..########`,`#######..#############..########`,`#######..##############..#######`,`#######..##############..#######`,`#######..##############..#######`,`################################`,`################################`],background:`cesarea-torg.webp`,mood:`calm`,decor:[{kind:`hoof`,x:12.5,y:8.6,angle:96},{kind:`hoof`,x:12.4,y:9.6,angle:96},{kind:`hoof`,x:12.3,y:10.5,angle:96},{kind:`hoof`,x:11.6,y:11.4,angle:128},{kind:`hoof`,x:10.6,y:12.3,angle:138},{kind:`hoof`,x:9.5,y:13.2,angle:141},{kind:`hoof`,x:8.4,y:14.1,angle:141},{kind:`hoof`,x:7.6,y:15.2,angle:126}],areas:[{id:`skrivestue`,map:[`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`######.....#########......######`,`######......########......######`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#############......#############`,`#############......#############`,`#############......#############`,`################################`,`################################`,`################################`],background:`skrivestue.webp`,scale:1.8,ambience:`street`},{id:`verksted`,map:[`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`######......########......######`,`######......########......######`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####.....................######`,`#####.....................######`,`#############......#############`,`#############......#############`,`#############......#############`,`################################`,`################################`,`################################`],background:`verksted.webp`,scale:1.8,ambience:`hearth`,decor:[{kind:`paw`,x:15.12,y:6.76,angle:151},{kind:`paw`,x:14.37,y:7.54,angle:155},{kind:`paw`,x:13.24,y:7.65,angle:157},{kind:`paw`,x:12.27,y:8.45,angle:156},{kind:`paw`,x:11.04,y:8.65,angle:158},{kind:`paw`,x:10.05,y:9.35,angle:162},{kind:`paw`,x:8.87,y:9.34,angle:169},{kind:`paw`,x:7.88,y:9.76,angle:-174},{kind:`paw`,x:7.05,y:9.15,angle:-162},{kind:`ring`,x:5.75,y:8.3,angle:0},{kind:`paw`,x:5.55,y:8.75,angle:-150},{kind:`shard`,x:4.7,y:10.4,angle:20},{kind:`shard`,x:6.3,y:10.7,angle:-70},{kind:`shard`,x:5.5,y:11.1,angle:130}]},{id:`konas-hus`,map:[`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`######......########......######`,`######......########......######`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#############......#############`,`#############......#############`,`#############......#############`,`################################`,`################################`,`################################`],background:`stue.webp`,scale:1.8,ambience:`hearth`}],start:{x:18,y:9},startArea:`skrivestue`,entities:[{id:`lukas`,kind:`person`,x:19,y:9,name:{nb:`Lukas`,en:`Luke`},look:`luke`,portrait:`lukas.webp`,interactions:[{not:[`oppdrag`],say:[{nb:`En kjerre med krukker har veltet på torget. Hør pottemakeren, eseldriveren og fiskeren på brygga, og se på kjerra selv.`,en:`A cart of jars has tipped over in the market. Listen to the potter, the donkey driver and the fisherman on the pier, and look at the cart yourself.`}],set:[`oppdrag`]},{has:[`skilt-vitner`,`avgjort`],not:[`tavle-risset`],say:[{nb:`To saker løst. Før jeg forteller hvordan jeg arbeider: riss navnet mitt i voksen. Den som hjelper meg, må kunne skrive ned det vitnene sier.`,en:`Two cases solved. Before I tell you how I work: scratch my name in the wax. Whoever helps me must be able to write down what the witnesses say.`}],play:{game:`tablet`,title:{nb:`Riss navnet i voksen`,en:`Cut the name in the wax`},win:`tavle-risset`,data:{word:`ΛΟΥΚΑΣ`},key:!0}},{has:[`skilt-vitner`,`avgjort`,`tavle-risset`],not:[`forord`],say:[{nb:`Godt arbeid. Du spurte hvem som var der, og du lette etter noe som kunne bekrefte det de sa.`,en:`Good work. You asked who was there, and you looked for something that could confirm what they said.`},{nb:`Jeg var ikke der selv da Jesus gikk omkring. Derfor nøyer jeg meg ikke med det alle sier. Jeg bygger på dem som var øyenvitner fra begynnelsen, og jeg går nøye gjennom alt.`,en:`I was not there myself when Jesus went about. So I do not settle for what everyone says. I build on those who were eyewitnesses from the beginning, and I go carefully through it all.`},{nb:`Og jeg har sjelden et hjul å se på. Da må jeg sammenligne flere vitner og se om de støtter hverandre.`,en:`And I rarely have a wheel to look at. So I must compare several witnesses and see whether they support one another.`},{nb:`Vennen min Paulus sitter fanget her i Herodes’ palass og venter på dommen. Ventetiden bruker jeg til å skrive, og til det trenger jeg deg.`,en:`My friend Paul is held prisoner here in Herod’s palace, waiting for his verdict. I use the waiting time to write, and for that I need you.`},{nb:`Én sak til venter i vitneboka. Og nå kan du se deg om: Flere på torget trenger en som kan tenke.`,en:`One more case is waiting in the notebook. And now you can look around: others in the market need someone who can think.`}],set:[`forord`,`fakta:forordet`,`fakta:sjanger`,`fakta:lukas`,`fakta:diktet`]},{has:[`tavle-skrevet`],not:[`vitnemaal-levert`],say:[{nb:`Nedskrevet samme dag, med vitnets egne ord. Slik vil jeg ha det.`,en:`Written down the same day, in the witness’s own words. That is how I want it.`}],set:[`vitnemaal-levert`]},{not:[`forord`],say:[{nb:`Tre snakker om kjerra: pottemakeren, eseldriveren og fiskeren på brygga. Se på kjerra selv også. Sakene løser du i vitneboka.`,en:`Three people are talking about the cart: the potter, the donkey driver and the fisherman on the pier. Look at the cart yourself too. You solve the cases in the notebook.`}]},{has:[`overfort`],not:[],say:[{nb:`Nå kan du se deg om i byen. I morgen går vi til templet i Jerusalem, der boka mi begynner.`,en:`Now you can look around the town. Tomorrow we go to the temple in Jerusalem, where my book begins.`}],set:[]},{say:[{nb:`Se i vitneboka. Der venter det en sak til.`,en:`Look in the notebook. One more case is waiting there.`}]}],area:`skrivestue`},{id:`fisker`,kind:`person`,x:8,y:17,name:{nb:`Fiskeren`,en:`The fisherman`},look:`fisher`,portrait:`fisher.webp`,interactions:[{say:[{nb:`Kjerra? Jeg hørte smellet helt ut hit på brygga.`,en:`The cart? I heard the crash all the way out here on the pier.`},{nb:`Alle sier at en hund skremte eselet. Det har jeg hørt av minst fem stykker.`,en:`Everyone says a dog frightened the donkey. I have heard it from at least five people.`}],set:[`spor:fisker`]}]},{id:`pottemaker`,kind:`person`,x:18,y:8,name:{nb:`Pottemakeren`,en:`The potter`},look:`potter`,portrait:`potter.webp`,interactions:[{has:[`tavle`],not:[`tavle-skrevet`],say:[{nb:`Riss det inn: Jeg sto tre skritt unna. Hjulet knakk. Det var mine krukker.`,en:`Scratch it in: I stood three paces away. The wheel broke. They were my jars.`}],set:[`tavle-skrevet`]},{not:[`spor:pottemaker`],say:[{nb:`Jeg sto tre skritt unna. Det var mine krukker!`,en:`I was standing three steps away. Those were my jars!`},{nb:`Det var ingen hund der. Hjulet knakk, og hele lasset raste ut. Eselet sto helt stille.`,en:`There was no dog. The wheel broke, and the whole load came crashing down. The donkey stood perfectly still.`},{nb:`Skårene ligger spredt over hele torget. Finner du fem av dem, kan jeg se hvor mange krukker jeg har mistet.`,en:`The shards are scattered all over the square. If you find five of them, I can tell how many jars I have lost.`}],set:[`spor:pottemaker`]},{has:[`skaar:1`,`skaar:2`,`skaar:3`,`skaar:4`,`skaar:5`],not:[`skaar-levert`],say:[{nb:`Fem skår, og alle fra hver sin krukke. Fem krukker, altså.`,en:`Five shards, each from a different jar. Five jars, then.`},{nb:`Takk skal du ha. Nå vet jeg hva jeg skal kreve av eseldriveren.`,en:`Thank you. Now I know what to claim from the donkey driver.`}],set:[`skaar-levert`]},{has:[`katt-lost`],not:[`unnskyldt`],say:[{nb:`Så det var ikke gutten? Da skylder jeg ham en unnskyldning. Jeg var for rask til å dømme.`,en:`So it was not the boy? Then I owe him an apology. I was too quick to judge.`}],set:[`unnskyldt`]},{say:[{nb:`Hjulet knakk. Det så jeg med mine egne øyne.`,en:`The wheel broke. I saw it with my own eyes.`}]}]},{id:`kjorer`,kind:`person`,x:12,y:8,name:{nb:`Eseldriveren`,en:`The donkey driver`},look:`driver`,portrait:`driver.webp`,interactions:[{has:[`esel-funnet`],not:[`esel-takket`],say:[{nb:`Den hunden? Sov hele morgenen, sier de … Greit. Kanskje det ikke var noen hund.`,en:`That dog? Slept all morning, they say … All right. Maybe there was no dog.`}],set:[`esel-takket`]},{has:[`avgjort`],not:[`innrommet`],say:[{nb:`Greit, greit. Hjulet var dårlig, det har jeg visst lenge. Jeg skal betale for krukkene.`,en:`All right, all right. The wheel was bad, I have known that for a long time. I will pay for the jars.`}],set:[`innrommet`]},{say:[{nb:`Det var ikke min feil! En hund kom løpende og skremte eselet.`,en:`It was not my fault! A dog came running and frightened the donkey.`},{nb:`Skal jeg betale for krukkene, kanskje? Aldri i livet.`,en:`Am I supposed to pay for the jars? Never.`}],set:[`spor:kjorer`],not:[`spor:kjorer`]},{say:[{nb:`Det var ikke min feil, sier jeg!`,en:`It was not my fault, I tell you!`}]}]},{id:`kjerre`,kind:`thing`,x:13,y:7,name:{nb:`Den veltede kjerra`,en:`The overturned cart`},look:`cart`,portrait:`cart.webp`,interactions:[{say:[{nb:`Det ene hjulet ligger løst ved siden av kjerra. Eikene er råtne og knekt tvers av.`,en:`One wheel is lying loose beside the cart. The spokes are rotten and snapped clean through.`},{nb:`Eselet står fortsatt spent for kjerra og tygger rolig. Hjulsporene går rett fram og stopper brått.`,en:`The donkey is still harnessed to the cart, chewing calmly. The wheel tracks run straight and stop dead.`}],set:[`spor:kjerre`]}]},{id:`skaar-1`,kind:`thing`,x:10,y:5,name:{nb:`Et krukkeskår`,en:`A shard`},look:`shard`,portrait:`shards.webp`,hiddenWhen:`skaar:1`,interactions:[{say:[{nb:`Du plukker opp et krukkeskår.`,en:`You pick up a shard of pottery.`}],set:[`skaar:1`]}]},{id:`skaar-2`,kind:`thing`,x:19,y:6,name:{nb:`Et krukkeskår`,en:`A shard`},look:`shard`,portrait:`shards.webp`,hiddenWhen:`skaar:2`,interactions:[{say:[{nb:`Du plukker opp et krukkeskår.`,en:`You pick up a shard of pottery.`}],set:[`skaar:2`]}]},{id:`skaar-3`,kind:`thing`,x:16,y:10,name:{nb:`Et krukkeskår`,en:`A shard`},look:`shard`,portrait:`shards.webp`,hiddenWhen:`skaar:3`,interactions:[{say:[{nb:`Du plukker opp et krukkeskår.`,en:`You pick up a shard of pottery.`}],set:[`skaar:3`]}]},{id:`skaar-4`,kind:`thing`,x:19,y:7,name:{nb:`Et krukkeskår`,en:`A shard`},look:`shard`,portrait:`shards.webp`,hiddenWhen:`skaar:4`,interactions:[{say:[{nb:`Du plukker opp et krukkeskår.`,en:`You pick up a shard of pottery.`}],set:[`skaar:4`]}]},{id:`skaar-5`,kind:`thing`,x:22,y:13,name:{nb:`Et krukkeskår`,en:`A shard`},look:`shard`,portrait:`shards.webp`,hiddenWhen:`skaar:5`,interactions:[{say:[{nb:`Du plukker opp et krukkeskår.`,en:`You pick up a shard of pottery.`}],set:[`skaar:5`]}]},{id:`kone`,kind:`person`,x:9,y:9,name:{nb:`Den gamle kona`,en:`The old woman`},look:`oldwoman`,portrait:`oldwoman.webp`,interactions:[{has:[],not:[`forord`],say:[{nb:`Gå ærendet ditt for Lukas, du. Etterpå har jeg en liten bønn til deg.`,en:`Run your errand for Luke, dear. Afterwards I have a small favour to ask.`}],set:[]},{not:[`vann-oppdrag`],say:[{nb:`Krukka mi er tom, og knærne mine vil ikke mer. Kan du hente vann i brønnen for meg?`,en:`My jar is empty, and my knees have had enough. Could you fetch water from the well for me?`}],set:[`vann-oppdrag`]},{has:[`vann`],not:[`vann-levert`],say:[{nb:`Å, tusen takk! Gud velsigne deg.`,en:`Oh, thank you so much! God bless you.`}],set:[`vann-levert`]},{not:[`vann`],say:[{nb:`Brønnen ligger midt på torget.`,en:`The well is in the middle of the square.`}]},{say:[{nb:`Vannet smakte godt. Takk igjen.`,en:`The water tasted good. Thank you again.`}]}]},{id:`bronn`,kind:`thing`,x:16,y:7,name:{nb:`Brønnen`,en:`The well`},look:`hotspot`,portrait:`well.webp`,interactions:[{has:[`vann-oppdrag`],not:[`vann`],say:[{nb:`Du heiser opp bøtta og fyller krukka med kaldt vann.`,en:`You haul up the bucket and fill the jar with cold water.`}],set:[`vann`]},{say:[{nb:`En dyp brønn med kaldt vann.`,en:`A deep well with cold water.`}]}]},{id:`kjopmann`,kind:`person`,x:12,y:4,name:{nb:`Kjøpmannen`,en:`The merchant`},look:`scribe`,portrait:`scribe.webp`,interactions:[{has:[],not:[`forord`],say:[{nb:`For et rot! Men gå ærendet ditt for Lukas først. Etterpå kan du hjelpe meg.`,en:`What a mess! But run your errand for Luke first. Afterwards you can help me.`}],set:[]},{not:[`spor:krukker`],say:[{nb:`For et rot! Lærlingen min har satt feil lapp på alle tre krukkene: olje, honning og vann. Ikke én lapp er riktig.`,en:`What a mess! My apprentice has put the wrong label on all three jars: oil, honey and water. Not one label is right.`},{nb:`Jeg åpnet den som er merket «olje». Den var full av honning. Hva er i de to andre? Jeg vil vite det før jeg åpner dem.`,en:`I opened the one marked “oil”. It was full of honey. What is in the other two? I want to know before I open them.`}],set:[`spor:krukker`]},{not:[`krukker-lost`],say:[{nb:`Har du funnet ut hva som er i krukkene? Se i vitneboka di.`,en:`Have you worked out what is in the jars? Look in your notebook.`}]},{say:[{nb:`Du hadde rett om krukkene! Jeg skulle ansatt deg i stedet.`,en:`You were right about the jars! I should have hired you instead.`}]}]},{id:`jente`,kind:`person`,x:14,y:6,name:{nb:`Jenta ved brønnen`,en:`The girl by the well`},look:`girl`,portrait:`girl.webp`,interactions:[{has:[],not:[`forord`],say:[{nb:`Du er Lukas’ lærling, ikke sant? Gjør ferdig ærendet hans først. Så har jeg noe du kan finne ut.`,en:`You’re Luke’s apprentice, aren’t you? Finish his errand first. Then I have something for you to work out.`}],set:[]},{not:[`spor:jente`],say:[{nb:`I dag morges hvisket jeg en beskjed til broren min: «Skipet fra Alexandria kommer i morgen med korn.»`,en:`This morning I whispered a message to my brother: “The ship from Alexandria arrives tomorrow with corn.”`},{nb:`Han løp ned til brygga lengst til høyre for å si det videre. Kan du finne ut hva som har blitt av beskjeden min?`,en:`He ran down to the pier furthest to the right to pass it on. Can you find out what has become of my message?`}],set:[`spor:jente`]},{not:[`hviske-lost`],say:[{nb:`Broren min står på brygga lengst til høyre.`,en:`My brother is on the pier furthest to the right.`}]},{say:[{nb:`Horn?! Jeg sa korn! Hadde de bare spurt meg.`,en:`Horns?! I said corn! If only they had asked me.`}]}]},{id:`gutt`,kind:`person`,x:24,y:16,name:{nb:`Gutten på brygga`,en:`The boy on the pier`},look:`boy`,portrait:`boy.webp`,interactions:[{has:[`spor:jente`],not:[`spor:gutt`],say:[{nb:`Søsteren min? Ja, hun sa at skipet fra Alexandria kommer i morgen med horn. Rart, men det var det hun sa.`,en:`My sister? Yes, she said the ship from Alexandria arrives tomorrow with horns. Odd, but that is what she said.`},{nb:`Jeg sa det videre til bakeren.`,en:`I passed it on to the baker.`}],set:[`spor:gutt`]},{say:[{nb:`Jeg ser etter skip. Det er det beste jeg vet.`,en:`I am watching for ships. It is my favourite thing.`}]}]},{id:`baker`,kind:`person`,x:20,y:7,name:{nb:`Bakeren`,en:`The baker`},look:`trader`,portrait:`trader.webp`,interactions:[{has:[`spor:gutt`],not:[`spor:baker`],say:[{nb:`Har du hørt det? I morgen kommer det et skip fra Alexandria med hundre horn. Det må være et krigsskip!`,en:`Have you heard? Tomorrow a ship arrives from Alexandria with a hundred horns. It must be a warship!`},{nb:`Jeg har sagt det til halve byen alt.`,en:`I have told half the town already.`}],set:[`spor:baker`]},{say:[{nb:`Ferskt brød! Ennå varmt!`,en:`Fresh bread! Still warm!`}]}]},{id:`soldat`,kind:`person`,x:26,y:13,name:{nb:`Soldaten`,en:`The soldier`},look:`soldier`,portrait:`soldier.webp`,interactions:[{say:[{nb:`Gå videre. Kornet skal om bord før kvelden.`,en:`Move along. The corn must be on board before evening.`}]}]},{id:`dor-ut-skrivestue`,kind:`place`,x:15,y:17,name:{nb:`Torget`,en:`The square`},look:`hotspot`,door:{area:`main`,x:15,y:2},area:`skrivestue`},{id:`dor-skrivestue`,kind:`place`,x:14,y:2,name:{nb:`Lukas’ skrivestue`,en:`Luke’s writing room`},look:`hotspot`,door:{area:`skrivestue`,x:15,y:14}},{id:`dor-verksted`,kind:`place`,x:25,y:11,name:{nb:`Pottemakerens verksted`,en:`The potter’s workshop`},look:`hotspot`,door:{area:`verksted`,x:15,y:14}},{id:`dor-ut-verksted`,kind:`place`,x:15,y:17,name:{nb:`Torget`,en:`The square`},look:`hotspot`,door:{area:`main`,x:25,y:12},area:`verksted`},{id:`bokruller`,kind:`thing`,x:8,y:7,name:{nb:`Hylla med bokruller`,en:`The shelf of scrolls`},look:`hotspot`,area:`skrivestue`,interactions:[{say:[{nb:`Hylla er full av bokruller. Lukas har samlet det andre har skrevet før ham.`,en:`The shelf is full of scrolls. Luke has collected what others have written before him.`}],set:[`fakta:mange`]}]},{id:`vokstavle`,kind:`thing`,x:15,y:9,name:{nb:`Skrivebordet`,en:`The writing desk`},look:`hotspot`,area:`skrivestue`,interactions:[{has:[`spor:pottemaker`],not:[`tavle`],say:[{nb:`Du tar den ene tavla med deg ut. Pottemakeren skal få si det med egne ord.`,en:`You take one of the tablets with you. The potter can say it in his own words.`}],set:[`tavle`,`fakta:vokstavle`]},{has:[`fakta:vokstavle`],not:[],say:[{nb:`Lukas rekker deg griffelen: «Prøv. Riss navnet mitt i voksen, strek for strek, slik jeg har gjort det på tavla ved siden av.»`,en:`Luke hands you the stylus: “Try. Cut my name into the wax, stroke by stroke, as I have done on the tablet beside it.”`}],play:{game:`tablet`,title:{nb:`Riss navnet i voksen`,en:`Cut the name in the wax`},win:`tavle-risset`,data:{word:`ΛΟΥΚΑΣ`},key:!0}},{say:[{nb:`På bordet ligger to vokstavler bundet sammen. Notatene risses inn i voksen og kan glattes ut igjen.`,en:`On the desk lie two wax tablets tied together. Notes are scratched into the wax and can be smoothed out again.`}],set:[`fakta:vokstavle`]}]},{id:`laeregutt`,kind:`person`,x:11,y:11,name:{nb:`Læregutten`,en:`The potter’s boy`},look:`courier`,portrait:`courier.webp`,area:`verksted`,interactions:[{has:[],not:[`forord`],say:[{nb:`Mester er sint på meg. Kom tilbake når du er ferdig hos Lukas, så skal jeg fortelle.`,en:`The master is angry with me. Come back when you are done with Luke, and I’ll tell you.`}],set:[]},{not:[`katt-oppdrag`],say:[{nb:`Mester tror jeg knuste den fine krukka som sto på krakken ved hylla. Men jeg har ikke rørt den!`,en:`The master thinks I broke the fine jar that stood on the stool by the shelf. But I never touched it!`},{nb:`Se deg rundt, er du snill. Kanskje du finner ut hva som skjedde.`,en:`Please look around. Maybe you can find out what happened.`}],set:[`katt-oppdrag`]},{not:[`katt-lost`],say:[{nb:`Har du funnet noe? Se deg godt rundt.`,en:`Have you found anything? Take a good look around.`}]},{say:[{nb:`Takk! Nå tror mester meg.`,en:`Thank you! Now the master believes me.`}]}]},{id:`hylle`,kind:`thing`,x:6,y:8,name:{nb:`Krakken ved hylla`,en:`The stool by the shelf`},look:`hotspot`,area:`verksted`,interactions:[{say:[{nb:`På krakken er det en ren ring i støvet der en krukke har stått, og et lite, rundt avtrykk ved siden av. Skårene ligger på gulvet.`,en:`On the stool there is a clean ring in the dust where a jar stood, and a small, round print beside it. The shards lie on the floor.`}],set:[`spor:hylle`]}]},{id:`vindu`,kind:`thing`,x:16,y:9,name:{nb:`Gulvet under vinduet`,en:`The floor under the window`},look:`hotspot`,area:`verksted`,interactions:[{say:[{nb:`Vindusluka står på gløtt. Våte poteavtrykk går over gulvet og bort til krakken ved hylla.`,en:`The shutter is ajar. Wet paw prints cross the floor to the stool by the shelf.`}],set:[`spor:vindu`]}]},{id:`ovn`,kind:`thing`,x:24,y:8,name:{nb:`Ovnen`,en:`The kiln`},look:`hotspot`,area:`verksted`,interactions:[{say:[{nb:`Ovnen er kald. Ingen har brent krukker her i dag.`,en:`The kiln is cold. Nobody has fired any jars here today.`}]}]},{id:`kartet`,kind:`thing`,x:22,y:7,name:{nb:`Kartet over byen`,en:`The map of the town`},look:`hotspot`,area:`skrivestue`,interactions:[{has:[],not:[`forord`],say:[{nb:`Lukas’ kart over Cæsarea har falt i biter. Det får vente til ærendet er gjort.`,en:`Luke’s map of Caesarea has fallen to pieces. It can wait until the errand is done.`}],set:[]},{not:[`kart-lagt`],say:[{nb:`Lukas’ kart over Cæsarea har falt i biter. Legg det sammen igjen.`,en:`Luke’s map of Caesarea has fallen to pieces. Put it together again.`}],play:{game:`puzzle`,title:{nb:`Legg bildet sammen`,en:`Put the picture together`},win:`kart-lagt`,image:`maps/cesarea-torg.webp`}},{say:[{nb:`Kartet henger på plass igjen.`,en:`The map is back in its place.`}]}]},{id:`dor-konas-hus`,kind:`place`,x:6,y:9,name:{nb:`Den gamle konas hus`,en:`The old woman’s house`},look:`hotspot`,door:{area:`konas-hus`,x:15,y:14},locked:{until:`vann-levert`,say:{nb:`Døra er lukket. Kanskje den gamle kona slipper deg inn hvis du hjelper henne.`,en:`The door is closed. Perhaps the old woman will let you in if you help her.`}}},{id:`dor-ut-konas-hus`,kind:`place`,x:15,y:17,name:{nb:`Torget`,en:`The square`},look:`hotspot`,door:{area:`main`,x:6,y:10},area:`konas-hus`},{id:`vei-jerusalem`,kind:`place`,x:31,y:12,name:{nb:`Veien til Jerusalem`,en:`The road to Jerusalem`},look:`hotspot`,travelTo:`jerusalem`},{id:`garnet`,kind:`thing`,x:7,y:15,name:{nb:`Fiskegarnet`,en:`The fishing net`},look:`hotspot`,interactions:[{has:[],not:[`forord`],say:[{nb:`Fiskeren rister på hodet: «Garnet kan vente. Gå ærendet ditt for Lukas først.»`,en:`The fisherman shakes his head: “The net can wait. Run your errand for Luke first.”`}],set:[]},{say:[{nb:`Fiskeren nikker mot garnet: «Vil du prøve? Fisken står tett i dag.»`,en:`The fisherman nods at the net: “Want to try? There are plenty of fish today.”`}],play:{game:`fish`,title:{nb:`Fang fisken`,en:`Catch the fish`},win:`spill-garnet`}}]},{id:`hunden`,kind:`thing`,x:7,y:16,name:{nb:`Hunden ved garnet`,en:`The dog by the net`},look:`hotspot`,interactions:[{has:[`spor:kjorer`],not:[`esel-funnet`],say:[{nb:`Fiskerens hund ligger og sover i sola ved garnet. Fiskeren sier den ikke har rørt seg siden daggry.`,en:`The fisherman’s dog lies sleeping in the sun by the net. The fisherman says it has not moved since dawn.`}],set:[`esel-funnet`]},{has:[`esel-funnet`],say:[{nb:`Hunden sover videre. Den har ikke rørt seg siden daggry, sier fiskeren.`,en:`The dog sleeps on. It has not moved since dawn, the fisherman says.`}]},{say:[{nb:`En hund ligger og sover i sola ved garnet. Hvem sin er den?`,en:`A dog lies sleeping in the sun by the net. Whose is it?`}]}]},{id:`leke-baat`,kind:`thing`,x:24,y:17,name:{nb:`Båten ved brygga`,en:`The boat by the jetty`},look:`hotspot`,interactions:[{say:[{nb:`Du hopper oppi og dytter fra. Båten vugger, og en måke skriker sint over hodet ditt.`,en:`You jump in and push off. The boat rocks, and a gull screeches angrily over your head.`},{nb:`Fiskeren roper fra den andre brygga: «Lukas’ lærling skal skrive, ikke ro!»`,en:`The fisherman shouts from the other jetty: “Luke’s apprentice is meant to write, not row!”`}],fx:`rock`}]},{id:`leke-frukt`,kind:`thing`,x:13,y:3,name:{nb:`Fruktboden`,en:`The fruit stall`},look:`hotspot`,interactions:[{say:[{nb:`Granateplene triller over hele torget!`,en:`The pomegranates roll all over the square!`},{nb:`Fruktselgeren slår hendene sammen: «Plukk dem opp igjen, lærling! Hver eneste en!»`,en:`The fruit seller throws up her hands: “Pick them up again, apprentice! Every single one!”`}],fx:`tip`}]},{id:`leke-skaal`,kind:`thing`,x:14,y:13,name:{nb:`Bronseskåla`,en:`The bronze bowl`},look:`hotspot`,interactions:[{say:[{nb:`Den store bronseskåla synger når du slår på den. Soldaten lenger borte rynker på nesen.`,en:`The big bronze bowl sings when you strike it. The soldier further along wrinkles his nose.`}],fx:`ring`}]},{id:`leke-palme`,kind:`thing`,x:17,y:2,name:{nb:`Palmen`,en:`The palm tree`},look:`hotspot`,interactions:[{say:[{nb:`Du rister i stammen. En daddel dumper ned i håret ditt. Søt, og litt klissete.`,en:`You shake the trunk. A date drops into your hair. Sweet, and a little sticky.`}],fx:`shake`}]},{id:`leke-vinde`,kind:`thing`,x:17,y:5,name:{nb:`Brønnvinda`,en:`The well windlass`},look:`hotspot`,interactions:[{say:[{nb:`Vinda knirker rundt, og bøtta forsvinner ned i mørket.`,en:`The windlass creaks round and the bucket disappears into the dark.`},{nb:`Jenta ved brønnen ser på deg: «Du må dra den opp igjen også, vet du.»`,en:`The girl at the well looks at you: “You have to pull it up again too, you know.”`}],fx:`spin`}]}],facts:[{id:`forordet`,title:{nb:`Forordet til Lukas`,en:`Luke’s preface`},body:{nb:`Lukas åpner evangeliet med å fortelle hvordan han har arbeidet: Mange har skrevet før ham, stoffet kommer fra dem som var øyenvitner fra begynnelsen, og han har selv gått nøye gjennom alt (Luk 1,1–4).`,en:`Luke opens his Gospel by explaining how he has worked: many have written before him, the material comes from those who were eyewitnesses from the beginning, and he has gone carefully through everything himself (Luke 1:1–4).`},unlockedBy:`fakta:forordet`},{id:`sjanger`,title:{nb:`Hva slags bok er et evangelium?`,en:`What kind of book is a Gospel?`},body:{nb:`De fleste forskere regner i dag evangeliene som en form for antikk biografi: en fortelling om livet til en virkelig person. Sjangeren viser hva slags bok det er ment å være. Den viser ikke i seg selv at alt i boka er riktig. Det må undersøkes, og det er det du øver på.`,en:`Most scholars today regard the Gospels as a form of ancient biography: an account of the life of a real person. The genre shows what kind of book it is meant to be. It does not in itself show that everything in the book is correct. That has to be examined, and that is what you are practising.`},unlockedBy:`fakta:sjanger`},{id:`lukas`,title:{nb:`Hvem var Lukas?`,en:`Who was Luke?`},body:{nb:`Paulus nevner en lege som het Lukas, og regner ham blant medarbeiderne sine (Kol 4,14; Filem 24). Kirken har senest fra slutten av 100-tallet regnet ham som forfatter av Lukasevangeliet og Apostlenes gjerninger. Bøkene selv nevner ikke forfatteren ved navn. Mange forskere mener tradisjonen stemmer, andre er usikre.`,en:`Paul mentions a physician named Luke and counts him among his co-workers (Col 4:14; Philemon 24). At least since the late second century the church has regarded him as the author of the Gospel of Luke and the Acts of the Apostles. The books themselves do not name their author. Many scholars think the tradition is right; others are unsure.`},unlockedBy:`fakta:lukas`},{id:`diktet`,title:{nb:`Hva er funnet på i denne episoden?`,en:`What is made up in this episode?`},body:{nb:`Du som lærling, kjerra, fiskeren, pottemakeren og eseldriveren er funnet på for å øve. Det Lukas sier i spillet, er også funnet på, men bygger på forordet hans. Vi vet ikke hvor Lukas samlet stoffet sitt. Spillet legger det til havnebyen Cæsarea, fordi Apostlenes gjerninger forteller at Paulus satt fengslet der i to år, og fortelleren skriver «vi» både før og etter (Apg 21,8; 24,27; 27,1). At fortelleren var i området disse årene, er en rimelig gjetning, ikke noe teksten sier. Kjøpmannen, jenta, gutten, bakeren, den gamle kona, soldaten, læregutten, fiskerens hund og dyret i verkstedet er også funnet på. Det samme er skrivestua: Vi vet ikke hvilke skrifter Lukas hadde, eller hvor han oppbevarte dem.`,en:`You as the apprentice, the cart, the fisherman, the potter and the donkey driver are invented for practice. What Luke says in the game is also invented, though built on his preface. We do not know where Luke gathered his material. The game places it in the harbour city of Caesarea, because the Acts of the Apostles says Paul was imprisoned there for two years, and the narrator writes “we” both before and after (Acts 21:8; 24:27; 27:1). That the narrator was in the area during those years is a reasonable guess, not something the text says. The merchant, the girl, the boy, the baker, the old woman, the soldier, the potter’s boy, the fisherman’s dog and the animal in the workshop are also invented. So is the writing room: we do not know which writings Luke had, or where he kept them.`},unlockedBy:`fakta:diktet`},{id:`mange`,title:{nb:`Mange hadde skrevet før Lukas`,en:`Many had written before Luke`},body:{nb:`Lukas sier selv at mange før ham hadde forsøkt å skrive ned det som skjedde (Luk 1,1). De fleste forskere mener at Markusevangeliet var en av kildene han brukte. Når Markus ble skrevet, er omstridt.`,en:`Luke himself says that many before him had tried to write down what happened (Luke 1:1). Most scholars think the Gospel of Mark was one of the sources he used. When Mark was written is disputed.`},unlockedBy:`fakta:mange`},{id:`vokstavle`,title:{nb:`Vokstavler`,en:`Wax tablets`},body:{nb:`I romertiden var vokstavla en vanlig notatblokk. Man risset med en spiss griffel og kunne glatte ut voksen for å skrive på nytt. Sakarja ber om en slik tavle i Luk 1,63. Lengre tekster ble skrevet med blekk på papyrus.`,en:`In Roman times the wax tablet was a common notepad. People wrote by scratching with a pointed stylus, and could smooth the wax to write again. Zechariah asks for such a tablet in Luke 1:63. Longer texts were written in ink on papyrus.`},unlockedBy:`fakta:vokstavle`}],clues:[{id:`fisker`,source:{nb:`Fiskeren`,en:`The fisherman`},text:{nb:`Jeg var på brygga og hørte smellet. Alle sier at en hund skremte eselet.`,en:`I was on the pier and heard the crash. Everyone says a dog frightened the donkey.`},unlockedBy:`spor:fisker`},{id:`pottemaker`,source:{nb:`Pottemakeren`,en:`The potter`},text:{nb:`Jeg sto tre skritt unna. Hjulet knakk. Det var ingen hund, og eselet sto stille.`,en:`I was three steps away. The wheel broke. There was no dog, and the donkey stood still.`},unlockedBy:`spor:pottemaker`},{id:`kjorer`,source:{nb:`Eseldriveren`,en:`The donkey driver`},text:{nb:`En hund skremte eselet. Det var ikke min feil, og jeg betaler ikke for krukkene.`,en:`A dog frightened the donkey. It was not my fault, and I am not paying for the jars.`},unlockedBy:`spor:kjorer`},{id:`kjerre`,source:{nb:`Det du selv så`,en:`What you saw yourself`},text:{nb:`Hjulet har råtne eiker som er knekt. Eselet står rolig, og hjulsporene går rett fram og stopper brått.`,en:`The wheel has rotten spokes that are snapped. The donkey is calm, and the wheel tracks run straight and stop dead.`},unlockedBy:`spor:kjerre`},{id:`forordet`,source:{nb:`Lukas`,en:`Luke`},text:{nb:`Jeg bygger på dem som var øyenvitner fra begynnelsen, og jeg går nøye gjennom alt.`,en:`I build on those who were eyewitnesses from the beginning, and I go carefully through it all.`},unlockedBy:`forord`},{id:`lapper`,source:{nb:`Kjøpmannen`,en:`The merchant`},text:{nb:`Krukkene inneholder olje, honning og vann. Alle tre lappene er feil.`,en:`The jars contain oil, honey and water. All three labels are wrong.`},unlockedBy:`spor:krukker`},{id:`apnet`,source:{nb:`Kjøpmannen`,en:`The merchant`},text:{nb:`I krukka merket «olje» var det honning.`,en:`The jar marked “oil” contained honey.`},unlockedBy:`spor:krukker`},{id:`jente`,source:{nb:`Jenta ved brønnen`,en:`The girl by the well`},text:{nb:`Jeg sa: «Skipet fra Alexandria kommer i morgen med korn.»`,en:`I said: “The ship from Alexandria arrives tomorrow with corn.”`},unlockedBy:`spor:jente`},{id:`gutt`,source:{nb:`Gutten på brygga`,en:`The boy on the pier`},text:{nb:`Hun sa at skipet kommer i morgen med horn.`,en:`She said the ship arrives tomorrow with horns.`},unlockedBy:`spor:gutt`},{id:`baker`,source:{nb:`Bakeren`,en:`The baker`},text:{nb:`Det kommer et krigsskip med hundre horn.`,en:`A warship with a hundred horns is coming.`},unlockedBy:`spor:baker`},{id:`hylle`,source:{nb:`Det du selv så`,en:`What you saw yourself`},text:{nb:`En ren ring i støvet på krakken viser hvor krukka sto. Ved siden av er det et lite, rundt avtrykk.`,en:`A clean ring in the dust on the stool shows where the jar stood. Beside it is a small, round print.`},unlockedBy:`spor:hylle`},{id:`poter`,source:{nb:`Det du selv så`,en:`What you saw yourself`},text:{nb:`Vindusluka står på gløtt, og våte poteavtrykk går over gulvet bort til krakken.`,en:`The shutter is ajar, and wet paw prints cross the floor to the stool.`},unlockedBy:`spor:vindu`},{id:`laeregutt`,source:{nb:`Læregutten`,en:`The potter’s boy`},text:{nb:`Jeg har ikke rørt krukka som sto på krakken.`,en:`I never touched the jar that stood on the stool.`},unlockedBy:`katt-oppdrag`},{id:`krav`,source:{nb:`Pottemakeren`,en:`The potter`},unlockedBy:`skaar-levert`,text:{nb:`Fem krukker. Nå vet jeg hva jeg skal kreve av eseldriveren.`,en:`Five jars. Now I know what to claim from the donkey driver.`}}],deductions:[{id:`hvem-sa-det`,question:{nb:`Fiskeren og pottemakeren sier ulike ting. Hvorfor?`,en:`The fisherman and the potter say different things. Why?`},clues:[`fisker`,`pottemaker`],steps:[{ask:{nb:`Finn det fiskeren og pottemakeren sa om kjerra.`,en:`Find what the fisherman and the potter said about the cart.`},clues:[`fisker`,`pottemaker`],yes:{nb:`Ja. Hør: den ene sier «alle sier», den andre sier «jeg sto tre skritt unna». Hva betyr det?`,en:`Yes. Listen: one says “everyone says”, the other “I stood three steps away”. What does it mean?`},no:{nb:`Ikke den. Finn det fiskeren og pottemakeren sa om velten.`,en:`Not that one. Find what the fisherman and the potter said about the crash.`}}],options:[{text:{nb:`Pottemakeren så det selv. Fiskeren gjentar andres ord.`,en:`The potter saw it himself. The fisherman repeats what others said.`},feedback:{nb:`Riktig. Det første du spør om, er: Var vitnet der selv? Fem som gjentar et rykte, er ikke fem vitner.`,en:`Correct. The first thing you ask is: was the witness there? Five people repeating a rumour are not five witnesses.`},correct:!0},{text:{nb:`En av dem lyver, ellers hadde de ikke fortalt det så ulikt.`,en:`One of them is lying, or they would not have told it so differently.`},feedback:{nb:`Ingen av dem trenger å lyve. Se på hvor hver av dem var da det skjedde.`,en:`Neither of them has to be lying. Look at where each of them was when it happened.`}},{text:{nb:`Fiskeren har rett, for han har hørt det av fem stykker.`,en:`The fisherman is right, because he heard it from five people.`},feedback:{nb:`At mange sier det samme, hjelper ikke hvis vi ikke vet om noen av dem var der. Hvem av de to så det selv?`,en:`Many people saying the same thing does not help if we do not know whether any of them were there. Which of the two saw it himself?`}}],set:[`skilt-vitner`]},{id:`hvem-tro`,question:{nb:`Pottemakeren og eseldriveren var der begge to. Hvem skal du tro?`,en:`The potter and the donkey driver were both there. Who should you believe?`},clues:[`pottemaker`,`kjorer`,`kjerre`],steps:[{ask:{nb:`Hva sa pottemakeren og eseldriveren om velten, de to som var der?`,en:`What did the potter and the donkey driver say about the crash, the two who were there?`},clues:[`pottemaker`,`kjorer`],yes:{nb:`To som var der, og de sier det motsatte. Da trenger vi noe som ikke kan lyve. Hva så du selv ved kjerra?`,en:`Two who were there, and they say the opposite. Then we need something that cannot lie. What did you see at the cart yourself?`},no:{nb:`Ikke den. Finn det pottemakeren og eseldriveren sa om velten.`,en:`Not that one. Find what the potter and the donkey driver said about the crash.`}},{ask:{nb:`Hva så du selv ved kjerra?`,en:`What did you see at the cart yourself?`},clues:[`kjerre`],yes:{nb:`Råtne eiker, et rolig esel, spor som stopper brått. Hvem passer det med?`,en:`Rotten spokes, a calm donkey, tracks that stop short. Who does that fit?`},no:{nb:`Ikke den. Finn det du selv så ved kjerra.`,en:`Not that one. Find what you saw at the cart yourself.`}}],options:[{text:{nb:`Pottemakeren. Det jeg selv så ved kjerra, passer med det han sier.`,en:`The potter. What I saw myself at the cart fits what he says.`},feedback:{nb:`Riktig. Begge har noe å vinne, så du lot sporene avgjøre: råttent hjul, rolig esel og rette hjulspor. Det er den beste forklaringen, selv om du ikke så det skje.`,en:`Correct. Both have something to gain, so you let the traces decide: a rotten wheel, a calm donkey and straight wheel tracks. It is the best explanation, even though you did not see it happen.`},correct:!0},{text:{nb:`Eseldriveren. Han kjørte kjerra og vet best hva som skjedde.`,en:`The donkey driver. He was driving the cart and knows best what happened.`},feedback:{nb:`Han var nærmest, det er sant. Men hva taper han hvis hjulet hans var dårlig? Og hva har du selv sett som kan avgjøre det?`,en:`He was closest, that is true. But what does he lose if his wheel was bad? And what have you seen yourself that could settle it?`}},{text:{nb:`Ingen av dem. Da kan vi aldri få vite hva som skjedde.`,en:`Neither. Then we can never know what happened.`},feedback:{nb:`Det er riktig at begge har noe å vinne. Men det betyr ikke at vi må gi opp. Finnes det spor som ikke har noen grunn til å lyve?`,en:`It is true that both have something to gain. But that does not mean we must give up. Are there traces that have no reason to lie?`}}],set:[`avgjort`],hint:{nb:`Du trenger begge som var der, og noe du selv har sett som kan avgjøre mellom dem.`,en:`You need both people who were there, and something you have seen yourself that can decide between them.`}},{id:`hvem-leter-lukas-etter`,question:{nb:`Les det Lukas sier om arbeidet sitt. Hvilket vitne i kjerresaken ligner mest på dem han bygger på?`,en:`Read what Luke says about his work. Which witness in the cart case is most like those he builds on?`},clues:[`forordet`],steps:[{ask:{nb:`Hva sa jeg om hvem jeg bygger på?`,en:`What did I say about who I build on?`},clues:[`forordet`],yes:{nb:`Øyenvitner fra begynnelsen, og alt undersøkt grundig. Hvem i kjerresaken ligner mest på det?`,en:`Eyewitnesses from the beginning, and everything gone through with care. Who in the cart case is most like that?`}}],options:[{text:{nb:`Pottemakeren. Han så det selv, og det han sa, lot seg bekrefte.`,en:`The potter. He saw it himself, and what he said could be confirmed.`},feedback:{nb:`Riktig. Jeg bygger på dem som selv så og hørte. Eseldriveren var også der: Å ha vært der er det første kravet, ikke det eneste. I morgen går vi til templet i Jerusalem.`,en:`Right. I build on those who saw and heard for themselves. The donkey driver was there too: being there is the first requirement, not the only one. Tomorrow we go to the temple in Jerusalem.`},correct:!0},{text:{nb:`Fiskeren. Han kjenner mange i byen.`,en:`The fisherman. He knows many people in town.`},feedback:{nb:`Å kjenne mange er ikke det samme som å ha vært der. Hør en gang til hva jeg sa at jeg leter etter.`,en:`Knowing many people is not the same as having been there. Listen once more to what I said I am looking for.`}},{text:{nb:`Eseldriveren. Han sto nærmest.`,en:`The donkey driver. He stood closest.`},feedback:{nb:`Han var øyenvitne, ja. Men passet det han sa, med sporene?`,en:`He was an eyewitness, yes. But did what he said fit the traces?`}}],set:[`overfort`]},{id:`tre-krukker`,question:{nb:`Hva er i de to krukkene kjøpmannen ikke har åpnet?`,en:`What is in the two jars the merchant has not opened?`},clues:[`lapper`,`apnet`],steps:[{ask:{nb:`Hva vet vi fra kjøpmannen om lappene og krukkene?`,en:`What do we know from the merchant about the labels and the jars?`},clues:[`lapper`,`apnet`],yes:{nb:`Alle lappene er feil, og i «olje» var det honning. Da kan vi regne.`,en:`Every label is wrong, and in “oil” there was honey. Then we can work it out.`},no:{nb:`Det handler ikke om kjøpmannens krukker.`,en:`That is not about the merchant’s jars.`}}],options:[{text:{nb:`Krukka merket «honning» har vann, og krukka merket «vann» har olje.`,en:`The jar marked “honey” has water, and the jar marked “water” has oil.`},feedback:{nb:`Riktig. Krukka merket «vann» kan ikke ha vann, og honningen er alt funnet. Da må den ha olje, og vannet er i den siste. Du fant det ut uten å åpne dem.`,en:`Correct. The jar marked “water” cannot hold water, and the honey has already been found. So it must hold oil, and the water is in the last one. You worked it out without opening them.`},correct:!0},{text:{nb:`Krukka merket «honning» har olje, og krukka merket «vann» har vann.`,en:`The jar marked “honey” has oil, and the jar marked “water” has water.`},feedback:{nb:`Da ville lappen «vann» vært riktig. Men kjøpmannen sa at alle lappene er feil.`,en:`Then the label “water” would be right. But the merchant said all the labels are wrong.`}},{text:{nb:`Det går ikke an å vite før kjøpmannen har åpnet begge de andre krukkene.`,en:`There is no way to know until the merchant has opened both of the other jars.`},feedback:{nb:`Jo, det går. Begynn med krukka merket «vann». Hva kan den ikke inneholde?`,en:`Yes, it is possible. Start with the jar marked “water”. What can it not contain?`}}],set:[`krukker-lost`]},{id:`hviskeleken`,question:{nb:`Hva skjedde med beskjeden til jenta?`,en:`What happened to the girl’s message?`},clues:[`jente`,`gutt`,`baker`],steps:[{ask:{nb:`Hvem har sagt noe om skipet som kommer?`,en:`Who has said something about the ship that is coming?`},clues:[`jente`,`gutt`,`baker`],yes:{nb:`Tre ledd. Les dem i den rekkefølgen beskjeden gikk.`,en:`Three links. Read them in the order the message travelled.`},no:{nb:`Den der handler ikke om skipet.`,en:`That one is not about the ship.`}}],options:[{text:{nb:`Den endret seg for hvert ledd. Jenta, som sa den først, vet hva hun sa.`,en:`It changed at every link. The girl, who said it first, knows what she said.`},feedback:{nb:`Riktig. En beskjed som går gjennom mange ledd uten at noen sjekker, kan endre seg underveis. Derfor nøyer jeg meg ikke med det siste leddet. Jeg går tilbake til dem som var der fra begynnelsen.`,en:`Correct. A message that passes through many links without anyone checking can change along the way. That is why I do not settle for the last link. I go back to those who were there from the beginning.`},correct:!0},{text:{nb:`Bakeren har rett, for han har sagt det til flest, og ingen har sagt ham imot.`,en:`The baker is right, for he has told the most people, and nobody has contradicted him.`},feedback:{nb:`Å si noe til mange gjør det ikke riktigere. Hvem av de tre vet hva som ble sagt først?`,en:`Telling many people does not make it more correct. Which of the three knows what was said first?`}},{text:{nb:`En av dem løy med vilje, ellers hadde beskjeden vært lik hele veien.`,en:`One of them lied on purpose, or the message would have stayed the same all the way.`},feedback:{nb:`Ingen trengte å lyve. Gutten hørte feil, og bakeren la til litt. Hvem bør du spørre for å få vite hva som ble sagt?`,en:`Nobody needed to lie. The boy misheard, and the baker added a little. Who should you ask to find out what was said?`}}],set:[`hviske-lost`]},{id:`hvem-knuste`,question:{nb:`Hvem knuste krukka i verkstedet?`,en:`Who broke the jar in the workshop?`},clues:[`hylle`,`poter`,`laeregutt`],steps:[{ask:{nb:`Hva så du selv i verkstedet?`,en:`What did you see in the workshop yourself?`},clues:[`hylle`,`poter`],yes:{nb:`En ring i støvet, et lite avtrykk, og våte poter fra vinduet. Og hva sier læregutten?`,en:`A ring in the dust, a small print, and wet paws from the window. And what does the boy say?`},no:{nb:`Det er ikke noe du så i verkstedet.`,en:`That is not something you saw in the workshop.`}},{ask:{nb:`Og hva sier læregutten?`,en:`And what does the boy say?`},clues:[`laeregutt`],yes:{nb:`Han sier han ikke rørte den. Passer det med sporene?`,en:`He says he did not touch it. Does that fit the traces?`},no:{nb:`Det er ikke læregutten som sier det.`,en:`That is not the boy speaking.`}}],options:[{text:{nb:`Et dyr, trolig en katt. Det kom inn gjennom vinduet og hoppet opp på krakken.`,en:`An animal, probably a cat. It came in through the window and jumped onto the stool.`},feedback:{nb:`Riktig. Gutten har noe å vinne på å nekte, så ordet hans alene avgjør ikke. Det gjør sporene, og de peker på et dyr. Det er lett å skylde på den som står nærmest.`,en:`Correct. The boy has something to gain by denying it, so his word alone does not settle it. The traces do, and they point to an animal. It is easy to blame whoever is standing nearest.`},correct:!0},{text:{nb:`Læregutten. Han var den eneste i verkstedet.`,en:`The boy. He was the only one in the workshop, so nobody else could have done it.`},feedback:{nb:`Han var der, det stemmer. Men passer avtrykket på krakken med en gutt?`,en:`He was there, that is true. But does the print on the stool fit a boy?`}},{text:{nb:`Vinden. Den blåste inn gjennom vinduet og veltet krukka.`,en:`The wind. It blew in through the window and knocked the jar over.`},feedback:{nb:`Vinden setter ikke avtrykk i støvet. Hva viser ringen og avtrykket på krakken?`,en:`The wind leaves no prints in the dust. What do the ring and the print on the stool show?`}}],set:[`katt-lost`],hint:{nb:`Ta med det læregutten sier, og de to tingene du selv har sett i verkstedet.`,en:`Include what the boy says, and the two things you have seen yourself in the workshop.`}},{id:`hvem-vinner`,question:{nb:`Hvem av de to har noe å vinne på sin egen forklaring?`,en:`Which of the two has something to gain from his own explanation?`},clues:[`kjorer`,`krav`],steps:[{ask:{nb:`Hva sier eseldriveren om betalingen?`,en:`What does the donkey driver say about paying?`},clues:[`kjorer`],yes:{nb:`«Jeg betaler ikke.» Legg merke til det. Og hva skal pottemakeren kreve?`,en:`“I will not pay.” Note that. And what will the potter demand?`},no:{nb:`Det er ikke eseldriveren.`,en:`That is not the donkey driver.`}},{ask:{nb:`Og hva sier pottemakeren om det han skal kreve?`,en:`And what does the potter say about what he will claim?`},clues:[`krav`],yes:{nb:`Fem krukker. Nå har begge noe på spill. Hva betyr det?`,en:`Five jars. Now both have something at stake. What does it mean?`},no:{nb:`Det sier ikke noe om kravet.`,en:`That says nothing about the claim.`}}],hint:{nb:`Se etter hva eseldriveren slipper, og hva pottemakeren får.`,en:`Look for what the donkey driver avoids, and what the potter receives.`},options:[{text:{nb:`Bare eseldriveren. Han slipper å betale for fem krukker.`,en:`Only the donkey driver. He gets out of paying for five jars.`},feedback:{nb:`Han har noe å vinne, ja. Men hva får pottemakeren hvis hjulet har skylden?`,en:`He has something to gain, yes. But what does the potter get if the wheel is to blame?`}},{text:{nb:`Begge. Den ene slipper å betale, den andre får betalt.`,en:`Both. One avoids paying, the other gets paid.`},feedback:{nb:`Riktig. Å ha noe å vinne betyr ikke at man lyver. Men da må du finne noe annet som kan bekrefte det som blir sagt.`,en:`Correct. Having something to gain does not mean someone is lying. But then you must find something else that can confirm what is said.`},correct:!0},{text:{nb:`Ingen av dem. De forteller bare det de så.`,en:`Neither. They are only telling what they saw.`},feedback:{nb:`Begge var der, det stemmer. Men spør deg: Hvem må betale, og hvem får penger?`,en:`Both were there, that is true. But ask yourself: who has to pay, and who gets money?`}}],set:[`motiv-lost`]}],objectives:[{text:{nb:`Snakk med Lukas`,en:`Talk to Luke`},doneBy:[`oppdrag`]},{text:{nb:`Gå ut på torget. Hør på pottemakeren, eseldriveren og fiskeren på brygga, og se på kjerra`,en:`Go out to the square. Listen to the potter, the donkey driver and the fisherman on the pier, and look at the cart`},doneBy:[`spor:fisker`,`spor:pottemaker`,`spor:kjorer`,`spor:kjerre`]},{text:{nb:`Åpne vitneboka og løs de to sakene om kjerra`,en:`Open the notebook and solve the two cases about the cart`},doneBy:[`skilt-vitner`,`avgjort`]},{text:{nb:`Gå tilbake til Lukas i skrivestua og riss navnet hans i voksen`,en:`Go back to Luke in the writing room, and scratch his name in the wax`},doneBy:[`forord`,`tavle-risset`]},{text:{nb:`Løs saken om hvem Lukas bygger på`,en:`Solve the case of who Luke builds on`},doneBy:[`overfort`]}],rewards:[{flag:`skilt-vitner`,points:10,label:{nb:`Skill øyenvitnet fra ryktet`,en:`Tell the eyewitness from the rumour`},side:!1},{flag:`avgjort`,points:15,label:{nb:`Finn den beste forklaringen`,en:`Find the best explanation`},side:!1},{flag:`overfort`,points:10,label:{nb:`Forstå hva Lukas bygger på`,en:`Understand what Luke builds on`},side:!1},{flag:`hviske-lost`,points:20,label:{nb:`Spor beskjeden tilbake til kilden`,en:`Trace the message back to its source`},side:!0},{flag:`krukker-lost`,points:15,label:{nb:`Løs gåten med krukkene`,en:`Solve the riddle of the jars`},side:!0},{flag:`vann-levert`,points:10,label:{nb:`Hjelp den gamle kona`,en:`Help the old woman`},side:!0},{flag:`skaar-levert`,points:20,label:{nb:`Finn alle skårene`,en:`Find all the shards`},side:!0},{flag:`katt-lost`,points:15,label:{nb:`Frikjenn læregutten`,en:`Clear the potter’s boy`},side:!0},{flag:`fakta:mange`,points:5,label:{nb:`Undersøk bokrullene`,en:`Examine the scrolls`},side:!0},{flag:`fakta:vokstavle`,points:5,label:{nb:`Undersøk vokstavlene`,en:`Examine the wax tablets`},side:!0},{flag:`innrommet`,points:5,label:{nb:`Få eseldriveren til å innrømme det`,en:`Get the donkey driver to admit it`},side:!0},{flag:`unnskyldt`,points:5,label:{nb:`Få pottemakeren til å angre`,en:`Get the potter to say sorry`},side:!0},{flag:`motiv-lost`,points:10,label:{nb:`Se hvem som har noe å vinne`,en:`See who has something to gain`},side:!0},{flag:`kart-lagt`,points:10,label:{nb:`Legg kartet sammen`,en:`Put the map together`},side:!0},{flag:`spill-garnet`,points:10,label:{nb:`Fang fisken`,en:`Catch the fish`},side:!0},{flag:`esel-takket`,points:10,label:{nb:`Finn hunden alle snakker om`,en:`Find the dog everyone is talking about`},side:!0},{flag:`vitnemaal-levert`,points:10,label:{nb:`Få pottemakerens vitnemål ned på vokstavla`,en:`Get the potter’s statement down on the wax tablet`},side:!0},{flag:`tavle-risset`,points:10,label:{nb:`Riss navnet i voksen`,en:`Cut the name in the wax`},side:!0}],inventory:[{icon:`🏺`,label:{nb:`Krukkeskår`,en:`Shards`},flags:[`skaar:1`,`skaar:2`,`skaar:3`,`skaar:4`,`skaar:5`],goneWhen:`skaar-levert`},{icon:`💧`,label:{nb:`Krukke med vann`,en:`Jar of water`},flags:[`vann`],goneWhen:`vann-levert`},{icon:`📝`,label:{nb:`Vokstavle`,en:`Wax tablet`},flags:[`tavle`],goneWhen:`tavle-skrevet`}],ambience:[{sound:`sea`,x:8,y:16,radius:8},{sound:`sea`,x:16,y:16,radius:8},{sound:`sea`,x:23,y:16,radius:8},{sound:`market`,x:12,y:4,radius:5},{sound:`market`,x:21,y:6,radius:5},{sound:`market`,x:15,y:8,radius:4}],goal:[`overfort`],solution:`lukas.bokruller.vokstavle.vokstavle.dor-ut-skrivestue.fisker.pottemaker.kjorer.hunden.kjorer.kjerre.hvem-sa-det.hvem-tro.kjorer.skaar-1.skaar-2.skaar-3.skaar-4.skaar-5.pottemaker.hvem-vinner.dor-skrivestue.vokstavle.dor-ut-skrivestue.pottemaker.dor-skrivestue.lukas.lukas.kartet.dor-ut-skrivestue.garnet.kone.bronn.kone.dor-konas-hus.dor-ut-konas-hus.kjopmann.tre-krukker.jente.gutt.baker.hviskeleken.dor-verksted.laeregutt.hylle.vindu.hvem-knuste.dor-ut-verksted.pottemaker.hvem-leter-lukas-etter`.split(`.`)};export{e as default};